import{_ as s,c as a,d as e,o as t}from"./app-CHdsIfMu.js";const p={};function c(o,n){return t(),a("div",null,[...n[0]||(n[0]=[e(`<h1 id="gowind-shop-架构剖析-一个-rest-请求穿越三服务-bff-的七环链路" tabindex="-1"><a class="header-anchor" href="#gowind-shop-架构剖析-一个-rest-请求穿越三服务-bff-的七环链路"><span>GoWind Shop 架构剖析:一个 REST 请求穿越三服务 BFF 的七环链路</span></a></h1><h2 id="这篇在讲什么" tabindex="-1"><a class="header-anchor" href="#这篇在讲什么"><span>这篇在讲什么</span></a></h2><p>大多数微服务架构的文章停在&quot;我们用了 BFF 模式&quot;这种结论性描述,不讲 BFF 具体怎么装配、一个请求实际穿过了哪些代码、依赖图是怎么织起来的。这篇文章反过来:用一条真实的 <code>POST /admin/v1/mall/brands</code> 请求,把它从 HTTP 入站到 Ent 落库的每一个环节用代码钉死,再把支撑这条链路的 Wire 依赖注入和运行时配置逐行拆解。</p><p>文中所有代码和配置都来自一个真实仓库 go-wind-shop(GitHub: <a href="https://github.com/tx7do/go-wind-shop" target="_blank" rel="noopener noreferrer">https://github.com/tx7do/go-wind-shop</a>, Gitee: <a href="https://gitee.com/tx7do/go-wind-shop" target="_blank" rel="noopener noreferrer">https://gitee.com/tx7do/go-wind-shop</a>),标注了文件路径可核对。读完你会清楚三件事:这条链路怎么走、它由哪些配置决定、依赖图怎么从代码生成。</p><p>鉴权中间件内部的 token 校验和行级隔离细节,本文只点到为止——那是一整条纵深防御链,值得单独成篇,这里聚焦链路结构和依赖注入本身。</p><hr><h2 id="一、三服务-bff-职责分层的硬约束" tabindex="-1"><a class="header-anchor" href="#一、三服务-bff-职责分层的硬约束"><span>一、三服务 BFF:职责分层的硬约束</span></a></h2><p>先把全景画清楚。这个仓库的后端是三个 go-kratos 服务,职责严格分层:</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code><span class="line">HTTP/REST                                互联网客户端</span>
<span class="line">   │</span>
<span class="line">   ▼</span>
<span class="line">┌─────────────────────────┐         ┌─────────────────────────┐</span>
<span class="line">│  admin-service (BFF)    │         │  app-service (BFF)      │</span>
<span class="line">│  REST :6600  SSE :6601  │         │  REST :6700             │</span>
<span class="line">│  gRPC : 0.0.0.0:0(关闭) │         │  gRPC : 0.0.0.0:0(关闭) │</span>
<span class="line">│  ❌ 不碰 DB              │         │  ❌ 不碰 DB              │</span>
<span class="line">└───────────┬─────────────┘         └───────────┬─────────────┘</span>
<span class="line">            │ gRPC(经 etcd 服务发现)            │ gRPC</span>
<span class="line">            ▼                                    ▼</span>
<span class="line">        ┌───────────────────────────────────────────┐</span>
<span class="line">        │           core-service (核心实现)          │</span>
<span class="line">        │   gRPC only · ✅ 唯一持有 DB(Ent)          │</span>
<span class="line">        │   ✅ 唯一持有 Redis / Asynq / Authenticator │</span>
<span class="line">        └───────────────────────────────────────────┘</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>这张图的关键约束是表格化的——README 里直接列了:</p><table><thead><tr><th>服务</th><th>角色</th><th style="text-align:center;">是否访问 DB</th></tr></thead><tbody><tr><td><code>app/admin/service</code></td><td>后台网关 BFF</td><td style="text-align:center;">❌</td></tr><tr><td><code>app/app/service</code></td><td>前台网关 BFF</td><td style="text-align:center;">❌</td></tr><tr><td><code>app/core/service</code></td><td>核心业务实现</td><td style="text-align:center;">✅</td></tr></tbody></table><p>&quot;不碰 DB&quot;不是口头约束,是代码层面的硬约束。BFF 服务的 <code>internal/data/</code> 目录里没有 Ent client、没有 repo——它的 <code>wire_set.go</code> 里只有 Redis、MinIO、etcd discovery、gRPC client 工厂,没有任何 <code>NewXxxRepo</code>。而 core 服务的 <code>internal/data/</code> 里才有 <code>NewEntClient</code> 和全部 repo 工厂。这意味着 BFF 二进制里<strong>编译期就不存在数据访问的依赖</strong>,不是&quot;运行时选择不调&quot;。</p><p>这个约束的价值在于:把&quot;数据落点&quot;收敛到一处。后续做行级隔离、审计、脱敏,只需要在 core 一侧落实,BFF 即使被攻破也只是转发层,不直接碰数据。</p><hr><h2 id="二、请求全链路-七环节逐行追踪" tabindex="-1"><a class="header-anchor" href="#二、请求全链路-七环节逐行追踪"><span>二、请求全链路:七环节逐行追踪</span></a></h2><p>下面追踪 <code>POST /admin/v1/mall/brands</code> 这条请求。它要穿越七个环节,每个环节我都贴真实代码。</p><h3 id="环节-1-http-入站与路由分派" tabindex="-1"><a class="header-anchor" href="#环节-1-http-入站与路由分派"><span>环节 1:HTTP 入站与路由分派</span></a></h3><p>请求打到 admin BFF 的 kratos HTTP server,监听 <code>0.0.0.0:6600</code>(<code>app/admin/service/configs/server.yaml</code>):</p><div class="language-yaml line-numbers-mode" data-highlighter="prismjs" data-ext="yml"><pre><code><span class="line"><span class="token key atrule">server</span><span class="token punctuation">:</span></span>
<span class="line">  <span class="token key atrule">rest</span><span class="token punctuation">:</span></span>
<span class="line">    <span class="token key atrule">addr</span><span class="token punctuation">:</span> <span class="token string">&quot;0.0.0.0:6600&quot;</span></span>
<span class="line">    <span class="token key atrule">enable_swagger</span><span class="token punctuation">:</span> <span class="token boolean important">true</span></span>
<span class="line">    <span class="token key atrule">cors</span><span class="token punctuation">:</span> <span class="token punctuation">{</span> <span class="token key atrule">origins</span><span class="token punctuation">:</span> <span class="token punctuation">[</span><span class="token string">&quot;*&quot;</span><span class="token punctuation">]</span><span class="token punctuation">,</span> <span class="token key atrule">methods</span><span class="token punctuation">:</span> <span class="token punctuation">[</span><span class="token punctuation">...</span><span class="token punctuation">]</span><span class="token punctuation">,</span> <span class="token key atrule">headers</span><span class="token punctuation">:</span> <span class="token punctuation">[</span><span class="token punctuation">...</span><span class="token punctuation">]</span> <span class="token punctuation">}</span></span>
<span class="line">    <span class="token key atrule">middleware</span><span class="token punctuation">:</span></span>
<span class="line">      <span class="token key atrule">auth</span><span class="token punctuation">:</span> <span class="token punctuation">{</span> <span class="token key atrule">method</span><span class="token punctuation">:</span> <span class="token string">&quot;HS256&quot;</span><span class="token punctuation">,</span> <span class="token key atrule">key</span><span class="token punctuation">:</span> <span class="token string">&quot;some_api_key&quot;</span> <span class="token punctuation">}</span></span>
<span class="line">  <span class="token key atrule">grpc</span><span class="token punctuation">:</span></span>
<span class="line">    <span class="token key atrule">addr</span><span class="token punctuation">:</span> <span class="token string">&quot;0.0.0.0:0&quot;</span>     <span class="token comment"># ← BFF 的 gRPC 端口设为 0,等于关闭</span></span>
<span class="line">  <span class="token key atrule">sse</span><span class="token punctuation">:</span></span>
<span class="line">    <span class="token key atrule">addr</span><span class="token punctuation">:</span> <span class="token string">&quot;0.0.0.0:6601&quot;</span></span>
<span class="line">    <span class="token key atrule">path</span><span class="token punctuation">:</span> <span class="token string">&quot;/events&quot;</span></span>
<span class="line">    <span class="token key atrule">auto_stream</span><span class="token punctuation">:</span> <span class="token boolean important">true</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>注意 <code>grpc.addr: &quot;0.0.0.0:0&quot;</code>——BFF 不对外提供 gRPC 服务,端口设 0 等于关闭。这个设计决策的踩坑点后面讲。</p><p>kratos 根据 proto 的 <code>google.api.http</code> 注解(<code>get: &quot;/admin/v1/mall/brands&quot;</code>)把路由分派到生成的 HTTP handler,handler 调用 <code>service.BrandService.List</code>(BFF 侧的实现)。这个 handler 是 <code>protoc-gen-go-http</code> 从 proto 生成的,不是手写的。</p><h3 id="环节-2-bff-中间件链装配" tabindex="-1"><a class="header-anchor" href="#环节-2-bff-中间件链装配"><span>环节 2:BFF 中间件链装配</span></a></h3><p>请求进入 handler 前,先穿过中间件链。<code>app/admin/service/internal/server/rest_server.go</code> 的 <code>NewRestMiddleware</code> 按序装配:</p><div class="language-go line-numbers-mode" data-highlighter="prismjs" data-ext="go"><pre><code><span class="line"><span class="token keyword">func</span> <span class="token function">NewRestMiddleware</span><span class="token punctuation">(</span>ctx <span class="token operator">*</span>bootstrap<span class="token punctuation">.</span>Context<span class="token punctuation">)</span> <span class="token punctuation">[</span><span class="token punctuation">]</span>middleware<span class="token punctuation">.</span>Middleware <span class="token punctuation">{</span></span>
<span class="line">    <span class="token keyword">var</span> ms <span class="token punctuation">[</span><span class="token punctuation">]</span>middleware<span class="token punctuation">.</span>Middleware</span>
<span class="line">    ms <span class="token operator">=</span> <span class="token function">append</span><span class="token punctuation">(</span>ms<span class="token punctuation">,</span> logging<span class="token punctuation">.</span><span class="token function">Server</span><span class="token punctuation">(</span>ctx<span class="token punctuation">.</span><span class="token function">GetLogger</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">)</span>            <span class="token comment">// ① 结构化请求日志</span></span>
<span class="line">    ms <span class="token operator">=</span> <span class="token function">append</span><span class="token punctuation">(</span>ms<span class="token punctuation">,</span> applogging<span class="token punctuation">.</span><span class="token function">Server</span><span class="token punctuation">(</span>                          <span class="token comment">// ② 防篡改审计</span></span>
<span class="line">        <span class="token function">WithWriteApiLogFunc</span><span class="token punctuation">(</span><span class="token operator">...</span><span class="token punctuation">)</span><span class="token punctuation">,</span></span>
<span class="line">        <span class="token function">WithWriteLoginLogFunc</span><span class="token punctuation">(</span><span class="token operator">...</span><span class="token punctuation">)</span><span class="token punctuation">,</span></span>
<span class="line">    <span class="token punctuation">)</span><span class="token punctuation">)</span></span>
<span class="line">    ms <span class="token operator">=</span> <span class="token function">append</span><span class="token punctuation">(</span>ms<span class="token punctuation">,</span> selector<span class="token punctuation">.</span><span class="token function">Server</span><span class="token punctuation">(</span>                            <span class="token comment">// ③ 鉴权 + 授权</span></span>
<span class="line">        auth<span class="token punctuation">.</span><span class="token function">Server</span><span class="token punctuation">(</span></span>
<span class="line">            auth<span class="token punctuation">.</span><span class="token function">WithAccessTokenChecker</span><span class="token punctuation">(</span>accessTokenChecker<span class="token punctuation">)</span><span class="token punctuation">,</span></span>
<span class="line">            auth<span class="token punctuation">.</span><span class="token function">WithInjectMetadata</span><span class="token punctuation">(</span><span class="token boolean">true</span><span class="token punctuation">)</span><span class="token punctuation">,</span></span>
<span class="line">            auth<span class="token punctuation">.</span><span class="token function">WithInjectEnt</span><span class="token punctuation">(</span><span class="token boolean">true</span><span class="token punctuation">)</span><span class="token punctuation">,</span></span>
<span class="line">        <span class="token punctuation">)</span><span class="token punctuation">,</span></span>
<span class="line">        authz<span class="token punctuation">.</span><span class="token function">Server</span><span class="token punctuation">(</span>authorizer<span class="token punctuation">)</span><span class="token punctuation">,</span></span>
<span class="line">    <span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">Match</span><span class="token punctuation">(</span>rpc<span class="token punctuation">.</span><span class="token function">NewRestWhiteListMatcher</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">Build</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span></span>
<span class="line">    <span class="token keyword">return</span> ms</span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>三个中间件的职责:</p><p><strong>① <code>logging.Server</code></strong>:kratos 内置的结构化请求日志,记录 method/path/status/latency。</p><p><strong>② <code>applogging.Server</code></strong>:防篡改审计中间件(<code>pkg/middleware/logging/</code>),trailing 阶段把请求信息(操作者、API、IP、latency、status)算 SHA-256 hash + ECDSA 签名后写入 core 的 audit gRPC 服务。它的内部实现是另一篇的主题,这里只确认它在这一环。</p><p><strong>③ <code>selector.Server(auth.Server(...), authz.Server(...)).Match(rpc.NewRestWhiteListMatcher())</code></strong>:这是关键环。<code>selector</code> 是 kratos 的条件中间件——<code>Match(whiteListMatcher)</code> 决定哪些请求要过 <code>auth.Server</code> + <code>authz.Server</code>,哪些跳过。白名单由 <code>rpc.AddWhiteList(adminV1.OperationAuthenticationServiceLogin, ...)</code> 显式填充,只有 Login、Captcha 这类端点跳过鉴权。其余所有请求必须穿 auth + authz。</p><p><code>auth.Server</code> 的内部逻辑(token 校验、viewer 注入)和 <code>authz.Server</code> 的策略判定,涉及完整的鉴权纵深,这里只点明它在链路里的位置。它的 fail-closed 行为和 Casbin/OPA 引擎的具体运作,留给专门的篇幅展开——本篇聚焦链路结构。</p><h3 id="环节-3-bff-service-转发-grpc" tabindex="-1"><a class="header-anchor" href="#环节-3-bff-service-转发-grpc"><span>环节 3:BFF service 转发 gRPC</span></a></h3><p>中间件链通过后,handler 调到 BFF 侧的 <code>service.BrandService.List</code>。<code>app/admin/service/internal/service/brand_service.go</code>:</p><div class="language-go line-numbers-mode" data-highlighter="prismjs" data-ext="go"><pre><code><span class="line"><span class="token keyword">type</span> BrandService <span class="token keyword">struct</span> <span class="token punctuation">{</span></span>
<span class="line">    adminV1<span class="token punctuation">.</span>BrandServiceHTTPServer            <span class="token comment">// 生成的 HTTP server 接口(protoc-gen-go-http)</span></span>
<span class="line">    log                <span class="token operator">*</span>log<span class="token punctuation">.</span>Helper</span>
<span class="line">    brandServiceClient catalogV1<span class="token punctuation">.</span>BrandServiceClient   <span class="token comment">// 生成的 gRPC client(protoc-gen-go-grpc)</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">func</span> <span class="token punctuation">(</span>s <span class="token operator">*</span>BrandService<span class="token punctuation">)</span> <span class="token function">List</span><span class="token punctuation">(</span>ctx context<span class="token punctuation">.</span>Context<span class="token punctuation">,</span> req <span class="token operator">*</span>paginationV1<span class="token punctuation">.</span>PagingRequest<span class="token punctuation">)</span> <span class="token punctuation">(</span><span class="token operator">*</span>catalogV1<span class="token punctuation">.</span>ListBrandResponse<span class="token punctuation">,</span> <span class="token builtin">error</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token keyword">return</span> s<span class="token punctuation">.</span>brandServiceClient<span class="token punctuation">.</span><span class="token function">List</span><span class="token punctuation">(</span>ctx<span class="token punctuation">,</span> req<span class="token punctuation">)</span>   <span class="token comment">// 直接转发 gRPC 到 core</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>注意这个 service 做的事有多薄:它实现了 <code>adminV1.BrandServiceHTTPServer</code>(HTTP 接口),持有 <code>catalogV1.BrandServiceClient</code>(gRPC client),方法体就是一行转发。</p><p>这就是&quot;瘦网关&quot;的字面含义——BFF service 不含业务逻辑,只做协议转换(HTTP → gRPC)和必要的上下文注入。</p><p>写操作(Create/Update)会多一步:从鉴权上下文取操作者 id,注入请求。看 <code>Create</code>:</p><div class="language-go line-numbers-mode" data-highlighter="prismjs" data-ext="go"><pre><code><span class="line"><span class="token keyword">func</span> <span class="token punctuation">(</span>s <span class="token operator">*</span>BrandService<span class="token punctuation">)</span> <span class="token function">Create</span><span class="token punctuation">(</span>ctx context<span class="token punctuation">.</span>Context<span class="token punctuation">,</span> req <span class="token operator">*</span>catalogV1<span class="token punctuation">.</span>CreateBrandRequest<span class="token punctuation">)</span> <span class="token punctuation">(</span><span class="token operator">*</span>emptypb<span class="token punctuation">.</span>Empty<span class="token punctuation">,</span> <span class="token builtin">error</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">    operator<span class="token punctuation">,</span> err <span class="token operator">:=</span> auth<span class="token punctuation">.</span><span class="token function">FromContext</span><span class="token punctuation">(</span>ctx<span class="token punctuation">)</span></span>
<span class="line">    <span class="token keyword">if</span> err <span class="token operator">!=</span> <span class="token boolean">nil</span> <span class="token punctuation">{</span> <span class="token keyword">return</span> <span class="token boolean">nil</span><span class="token punctuation">,</span> err <span class="token punctuation">}</span></span>
<span class="line">    req<span class="token punctuation">.</span>Data<span class="token punctuation">.</span>CreatedBy <span class="token operator">=</span> trans<span class="token punctuation">.</span><span class="token function">Ptr</span><span class="token punctuation">(</span>operator<span class="token punctuation">.</span>UserId<span class="token punctuation">)</span>   <span class="token comment">// 注入操作者</span></span>
<span class="line">    <span class="token keyword">return</span> s<span class="token punctuation">.</span>brandServiceClient<span class="token punctuation">.</span><span class="token function">Create</span><span class="token punctuation">(</span>ctx<span class="token punctuation">,</span> req<span class="token punctuation">)</span>       <span class="token comment">// 转发 gRPC</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><code>auth.FromContext(ctx)</code> 取的是环节 2 里 <code>auth.Server</code> 中间件注入的 <code>UserTokenPayload</code>(从 JWT claims 解出来的操作者身份)。BFF 把 <code>CreatedBy</code> 塞进请求后转发——这个字段后续会映射到 Ent 的 <code>created_by</code> 列(由 <code>OperatorID</code> mixin 创建),完成操作者溯源。整条链路端到端,不靠业务代码自觉。</p><h3 id="环节-4-经-etcd-服务发现连-core" tabindex="-1"><a class="header-anchor" href="#环节-4-经-etcd-服务发现连-core"><span>环节 4:经 etcd 服务发现连 core</span></a></h3><p>BFF 持有的 <code>brandServiceClient</code> 是怎么连上 core 的?看 <code>app/admin/service/internal/data/data.go</code> 里的 client 工厂:</p><div class="language-go line-numbers-mode" data-highlighter="prismjs" data-ext="go"><pre><code><span class="line"><span class="token keyword">func</span> <span class="token function">NewBrandServiceClient</span><span class="token punctuation">(</span>ctx <span class="token operator">*</span>bootstrap<span class="token punctuation">.</span>Context<span class="token punctuation">,</span> discovery <span class="token operator">*</span>registry<span class="token punctuation">.</span>ServiceRegistry<span class="token punctuation">)</span> catalogV1<span class="token punctuation">.</span>BrandServiceClient <span class="token punctuation">{</span></span>
<span class="line">    <span class="token comment">// 用 etcd discovery 发现 core 服务的 gRPC 端点</span></span>
<span class="line">    <span class="token comment">// dial 出一个 gRPC client conn</span></span>
<span class="line">    <span class="token comment">// 返回 catalogV1.NewBrandServiceClient(conn) —— 生成代码封装</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>服务发现的后端在 <code>app/admin/service/configs/registry.yaml</code>:</p><div class="language-yaml line-numbers-mode" data-highlighter="prismjs" data-ext="yml"><pre><code><span class="line"><span class="token key atrule">registry</span><span class="token punctuation">:</span></span>
<span class="line">  <span class="token key atrule">type</span><span class="token punctuation">:</span> <span class="token string">&quot;etcd&quot;</span></span>
<span class="line">  <span class="token key atrule">endpoints</span><span class="token punctuation">:</span> <span class="token punctuation">[</span><span class="token string">&quot;localhost:2379&quot;</span><span class="token punctuation">]</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>注意一个设计细节:<strong>配置中心和服务发现用的是不同后端</strong>。<code>configs/remote.yaml</code> 指向 Consul 拉业务配置:</p><div class="language-yaml line-numbers-mode" data-highlighter="prismjs" data-ext="yml"><pre><code><span class="line"><span class="token key atrule">remote</span><span class="token punctuation">:</span></span>
<span class="line">  <span class="token key atrule">type</span><span class="token punctuation">:</span> <span class="token string">&quot;consul&quot;</span></span>
<span class="line">  <span class="token key atrule">key</span><span class="token punctuation">:</span> <span class="token string">&quot;go-wind-shop/admin/service&quot;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>而 <code>registry.yaml</code> 指向 etcd 做服务发现。两者职责分离——配置是相对静态的业务参数,服务发现是高频的实例寻址,用不同后端避免单点耦合。</p><p>连上 core 的 gRPC client 的中间件配置在 <code>app/admin/service/configs/client.yaml</code>:</p><div class="language-yaml line-numbers-mode" data-highlighter="prismjs" data-ext="yml"><pre><code><span class="line"><span class="token key atrule">client</span><span class="token punctuation">:</span></span>
<span class="line">  <span class="token key atrule">grpc</span><span class="token punctuation">:</span></span>
<span class="line">    <span class="token key atrule">timeout</span><span class="token punctuation">:</span> 120s</span>
<span class="line">    <span class="token key atrule">middleware</span><span class="token punctuation">:</span></span>
<span class="line">      <span class="token key atrule">enable_logging</span><span class="token punctuation">:</span> <span class="token boolean important">true</span></span>
<span class="line">      <span class="token key atrule">enable_recovery</span><span class="token punctuation">:</span> <span class="token boolean important">true</span></span>
<span class="line">      <span class="token key atrule">enable_tracing</span><span class="token punctuation">:</span> <span class="token boolean important">true</span>         <span class="token comment"># ← 跨服务调用延续 trace context</span></span>
<span class="line">      <span class="token key atrule">enable_circuit_breaker</span><span class="token punctuation">:</span> <span class="token boolean important">true</span> <span class="token comment"># ← 熔断</span></span>
<span class="line">      <span class="token key atrule">enable_validate</span><span class="token punctuation">:</span> <span class="token boolean important">true</span>        <span class="token comment"># ← protoc-gen-validate 校验出站请求</span></span>
<span class="line">      <span class="token key atrule">enable_metadata</span><span class="token punctuation">:</span> <span class="token boolean important">true</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>这里有几个值得注意的点:</p><ul><li><code>enable_tracing: true</code> 让 BFF → core 的 gRPC 调用延续 OpenTelemetry 的 trace context,Jaeger 里能看到跨服务调用链。</li><li><code>enable_circuit_breaker: true</code> 启用熔断,core 不可用时 BFF 快速失败而非雪崩。</li><li><code>enable_validate: true</code> 对出站请求也做校验——不只是入站校验,出站同样校验,防止 BFF 构造出非法请求发给 core。</li><li><code>timeout: 120s</code> 这个值偏长,电商场景的多数 RPC 不需要这么久,生产建议按 RPC 分级设超时。</li></ul><h3 id="环节-5-core-grpc-中间件" tabindex="-1"><a class="header-anchor" href="#环节-5-core-grpc-中间件"><span>环节 5:core gRPC 中间件</span></a></h3><p>请求到达 core 的 gRPC server。core 的 <code>internal/server/grpc_server.go</code> 注册了所有领域的 gRPC 服务:</p><div class="language-go line-numbers-mode" data-highlighter="prismjs" data-ext="go"><pre><code><span class="line"><span class="token keyword">func</span> <span class="token function">NewGrpcServer</span><span class="token punctuation">(</span>ctx <span class="token operator">*</span>bootstrap<span class="token punctuation">.</span>Context<span class="token punctuation">,</span> middlewares <span class="token punctuation">[</span><span class="token punctuation">]</span>middleware<span class="token punctuation">.</span>Middleware<span class="token punctuation">,</span> <span class="token operator">...</span><span class="token punctuation">)</span> <span class="token operator">*</span>kratos<span class="token punctuation">.</span>App <span class="token punctuation">{</span></span>
<span class="line">    srv<span class="token punctuation">,</span> err <span class="token operator">:=</span> rpc<span class="token punctuation">.</span><span class="token function">CreateGrpcServer</span><span class="token punctuation">(</span>ctx<span class="token punctuation">,</span> middlewares<span class="token operator">...</span><span class="token punctuation">)</span></span>
<span class="line">    catalogV1<span class="token punctuation">.</span><span class="token function">RegisterBrandServiceServer</span><span class="token punctuation">(</span>srv<span class="token punctuation">,</span> brandService<span class="token punctuation">)</span>      <span class="token comment">// 注册每个领域的 gRPC service</span></span>
<span class="line">    orderV1<span class="token punctuation">.</span><span class="token function">RegisterOrderServiceServer</span><span class="token punctuation">(</span>srv<span class="token punctuation">,</span> orderService<span class="token punctuation">)</span></span>
<span class="line">    identityV1<span class="token punctuation">.</span><span class="token function">RegisterUserServiceServer</span><span class="token punctuation">(</span>srv<span class="token punctuation">,</span> userService<span class="token punctuation">)</span></span>
<span class="line">    <span class="token comment">// ... 所有领域</span></span>
<span class="line">    <span class="token keyword">return</span> srv</span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>core 的 gRPC 中间件链在 <code>NewGrpcMiddleware</code>:</p><div class="language-go line-numbers-mode" data-highlighter="prismjs" data-ext="go"><pre><code><span class="line"><span class="token keyword">func</span> <span class="token function">NewGrpcMiddleware</span><span class="token punctuation">(</span>ctx <span class="token operator">*</span>bootstrap<span class="token punctuation">.</span>Context<span class="token punctuation">)</span> <span class="token punctuation">[</span><span class="token punctuation">]</span>middleware<span class="token punctuation">.</span>Middleware <span class="token punctuation">{</span></span>
<span class="line">    <span class="token keyword">var</span> ms <span class="token punctuation">[</span><span class="token punctuation">]</span>middleware<span class="token punctuation">.</span>Middleware</span>
<span class="line">    ms <span class="token operator">=</span> <span class="token function">append</span><span class="token punctuation">(</span>ms<span class="token punctuation">,</span> logging<span class="token punctuation">.</span><span class="token function">Server</span><span class="token punctuation">(</span>ctx<span class="token punctuation">.</span><span class="token function">GetLogger</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">)</span>   <span class="token comment">// 结构化日志</span></span>
<span class="line">    ms <span class="token operator">=</span> <span class="token function">append</span><span class="token punctuation">(</span>ms<span class="token punctuation">,</span> ent<span class="token punctuation">.</span><span class="token function">Server</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span>                       <span class="token comment">// viewer 重建</span></span>
<span class="line">    <span class="token keyword">return</span> ms</span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><code>ent.Server()</code>(<code>pkg/middleware/ent/</code>)做一件事:从入站 gRPC 的 metadata 头里,把 BFF 在环节 2/3 注入的 operator 信息还原成 <code>UserViewer</code>,挂进 Ent 的 viewer context。这个 viewer 携带 uid/tenantId/orgUnitId/dataScope,后续 Ent 的 privacy 策略会用它注入行级过滤。</p><p>如果 metadata 里缺 operator 信息(比如 BFF 没注入),<code>ent.Server()</code> 不会创建 viewer,后续 Ent privacy 策略发现无 viewer 会直接 fail-closed 报错——请求拿不到任何数据。这是&quot;无身份即无数据&quot;的链路实现。</p><h3 id="环节-6-core-service-→-repo" tabindex="-1"><a class="header-anchor" href="#环节-6-core-service-→-repo"><span>环节 6:core service → repo</span></a></h3><p>请求分派到 core 侧的 <code>service.BrandService.List</code>。<code>app/core/service/internal/service/brand_service.go</code>:</p><div class="language-go line-numbers-mode" data-highlighter="prismjs" data-ext="go"><pre><code><span class="line"><span class="token keyword">type</span> BrandService <span class="token keyword">struct</span> <span class="token punctuation">{</span></span>
<span class="line">    catalogV1<span class="token punctuation">.</span>UnimplementedBrandServiceServer     <span class="token comment">// 生成的 gRPC server 接口</span></span>
<span class="line">    log  <span class="token operator">*</span>log<span class="token punctuation">.</span>Helper</span>
<span class="line">    repo <span class="token operator">*</span>data<span class="token punctuation">.</span>BrandRepo                          <span class="token comment">// 持有 repo</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">func</span> <span class="token punctuation">(</span>s <span class="token operator">*</span>BrandService<span class="token punctuation">)</span> <span class="token function">List</span><span class="token punctuation">(</span>ctx context<span class="token punctuation">.</span>Context<span class="token punctuation">,</span> req <span class="token operator">*</span>paginationV1<span class="token punctuation">.</span>PagingRequest<span class="token punctuation">)</span> <span class="token punctuation">(</span><span class="token operator">*</span>catalogV1<span class="token punctuation">.</span>ListBrandResponse<span class="token punctuation">,</span> <span class="token builtin">error</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token keyword">return</span> s<span class="token punctuation">.</span>repo<span class="token punctuation">.</span><span class="token function">List</span><span class="token punctuation">(</span>ctx<span class="token punctuation">,</span> req<span class="token punctuation">)</span>   <span class="token comment">// 委托 repo</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>这里要讲一个和 kratos 教科书不一样的设计取舍。</p><p><strong>踩坑叙事:无 biz 层。</strong> kratos 的官方布局教程推荐四层:<code>server</code> → <code>service</code> → <code>biz</code> → <code>data</code>。其中 <code>biz</code> 是 use-case 层,定义业务逻辑;<code>service</code> 只做协议转换;<code>data</code> 做 ORM。这个仓库<strong>砍掉了 biz 层</strong>,service 直接调 data 的 repo。</p><p>我核对过整个 core 服务,<code>find -name biz</code> 没有任何结果。这是有意为之。取舍是:</p><ul><li><strong>好处</strong>:层数少,样板代码减半。简单 CRUD 领域(如 brand、category)的 service 就一行 <code>return s.repo.Xxx(ctx, req)</code>,中间多一层 biz 纯属噪音。</li><li><strong>代价</strong>:当某个领域的业务逻辑变复杂(如订单的状态机、支付的回调处理),service 会变厚。这时候需要自律地把复杂逻辑抽到 service 内部的私有方法,或拆分成多个 service。</li></ul><p>这个取舍适合&quot;业务逻辑较薄、以 CRUD 为主&quot;的脚手架场景。如果你的业务有大量领域规则,可能需要把 biz 层加回来。这是个明确的设计边界,不是疏漏。</p><h3 id="环节-7-repo-落库-ent-事务-级联" tabindex="-1"><a class="header-anchor" href="#环节-7-repo-落库-ent-事务-级联"><span>环节 7:repo 落库(Ent 事务 + 级联)</span></a></h3><p><code>app/core/service/internal/data/brand_repo.go</code> 的 <code>Create</code>:</p><div class="language-go line-numbers-mode" data-highlighter="prismjs" data-ext="go"><pre><code><span class="line"><span class="token keyword">func</span> <span class="token punctuation">(</span>r <span class="token operator">*</span>BrandRepo<span class="token punctuation">)</span> <span class="token function">Create</span><span class="token punctuation">(</span>ctx context<span class="token punctuation">.</span>Context<span class="token punctuation">,</span> req <span class="token operator">*</span>catalogV1<span class="token punctuation">.</span>CreateBrandRequest<span class="token punctuation">)</span> <span class="token punctuation">(</span><span class="token operator">*</span>catalogV1<span class="token punctuation">.</span>Brand<span class="token punctuation">,</span> <span class="token builtin">error</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">    tx<span class="token punctuation">,</span> err <span class="token operator">:=</span> r<span class="token punctuation">.</span>entClient<span class="token punctuation">.</span><span class="token function">Client</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">Tx</span><span class="token punctuation">(</span>ctx<span class="token punctuation">)</span>           <span class="token comment">// 开事务</span></span>
<span class="line">    <span class="token keyword">if</span> err <span class="token operator">!=</span> <span class="token boolean">nil</span> <span class="token punctuation">{</span> <span class="token keyword">return</span> <span class="token boolean">nil</span><span class="token punctuation">,</span> err <span class="token punctuation">}</span></span>
<span class="line">    <span class="token keyword">defer</span> <span class="token keyword">func</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">        <span class="token keyword">if</span> err <span class="token operator">!=</span> <span class="token boolean">nil</span> <span class="token punctuation">{</span> tx<span class="token punctuation">.</span><span class="token function">Rollback</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">}</span> <span class="token keyword">else</span> <span class="token punctuation">{</span> tx<span class="token punctuation">.</span><span class="token function">Commit</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">}</span></span>
<span class="line">    <span class="token punctuation">}</span><span class="token punctuation">(</span><span class="token punctuation">)</span></span>
<span class="line">    <span class="token comment">// 1. 主表写入</span></span>
<span class="line">    entBrand<span class="token punctuation">,</span> err <span class="token operator">:=</span> tx<span class="token punctuation">.</span>Brand<span class="token punctuation">.</span><span class="token function">Create</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">.</span></span>
<span class="line">        <span class="token function">SetNillableLogoURL</span><span class="token punctuation">(</span>req<span class="token punctuation">.</span>Data<span class="token punctuation">.</span><span class="token function">GetLogoURL</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">.</span></span>
<span class="line">        <span class="token function">Save</span><span class="token punctuation">(</span>ctx<span class="token punctuation">)</span></span>
<span class="line">    <span class="token keyword">if</span> err <span class="token operator">!=</span> <span class="token boolean">nil</span> <span class="token punctuation">{</span> <span class="token keyword">return</span> <span class="token boolean">nil</span><span class="token punctuation">,</span> err <span class="token punctuation">}</span></span>
<span class="line">    <span class="token comment">// 2. 级联翻译表写入(多语言,详见专门章节)</span></span>
<span class="line">    <span class="token keyword">if</span> err <span class="token operator">:=</span> r<span class="token punctuation">.</span>brandTranslationRepo<span class="token punctuation">.</span><span class="token function">BatchCreate</span><span class="token punctuation">(</span>ctx<span class="token punctuation">,</span> tx<span class="token punctuation">,</span> entBrand<span class="token punctuation">.</span>ID<span class="token punctuation">,</span> req<span class="token punctuation">.</span>Data<span class="token punctuation">.</span><span class="token function">GetTranslations</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span> err <span class="token operator">!=</span> <span class="token boolean">nil</span> <span class="token punctuation">{</span></span>
<span class="line">        <span class="token keyword">return</span> <span class="token boolean">nil</span><span class="token punctuation">,</span> err</span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line">    <span class="token comment">// 3. DTO 映射(ent entity → proto DTO)</span></span>
<span class="line">    <span class="token keyword">return</span> r<span class="token punctuation">.</span>mapper<span class="token punctuation">.</span><span class="token function">Convert</span><span class="token punctuation">(</span>entBrand<span class="token punctuation">)</span><span class="token punctuation">,</span> <span class="token boolean">nil</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>几个细节:</p><ul><li><p><strong>显式事务</strong>:<code>r.entClient.Client().Tx(ctx)</code> 开事务,defer 里按 err 决定 rollback/commit。主表和级联的翻译表在同一事务里,保证一致性。</p></li><li><p><strong><code>SetNillableLogoURL</code></strong>:Ent 生成的 builder 方法,<code>Nillable</code> 表示该字段可为 null,<code>Set</code> 系列方法只设置提供的字段。</p></li><li><p><strong><code>mapper.Convert</code></strong>:这个 repo 用 <code>mapper.CopierMapper[catalogV1.Brand, ent.Brand]</code> 做 ent entity 和 proto DTO 之间的转换。字段对应靠命名约定——proto DTO 的 <code>created_by</code> 映射到 ent entity 的 <code>created_by</code> 列(由 <code>OperatorID</code> mixin 创建)。这个映射器是 <code>github.com/tx7do/go-crud</code> 提供的通用工具,基于反射,按字段名匹配。</p></li><li><p><strong><code>List</code> 路径的行级过滤</strong>:List 请求经过 Ent privacy 策略时,如果该表挂了 <code>UserPrivacy</code>,Ent 会自动在 SQL 里注入 <code>WHERE &lt;user_column&gt; = &lt;viewer.uid&gt;</code>。注入是通过 <code>--feature entql</code> 提供的 <code>func(s *sql.Selector)</code> 钩子实现的,具体逻辑——这是行级隔离的核心,留给专门篇幅展开。</p></li></ul><h3 id="响应回程" tabindex="-1"><a class="header-anchor" href="#响应回程"><span>响应回程</span></a></h3><p>DTO 沿原路返回:repo → service → gRPC → BFF service → HTTP handler → 客户端。审计中间件在 trailing 阶段补记响应 status、latency、reason。</p><p>整条链路完成。</p><hr><h2 id="三、wire-依赖注入-从-providerset-到-wire-gen-go" tabindex="-1"><a class="header-anchor" href="#三、wire-依赖注入-从-providerset-到-wire-gen-go"><span>三、Wire 依赖注入:从 ProviderSet 到 wire_gen.go</span></a></h2><p>上面这条链路里出现的每个对象——<code>BrandService</code>、<code>BrandRepo</code>、<code>EntClient</code>、<code>Discovery</code>、<code>Authorizer</code>、<code>AccessTokenChecker</code>、HTTP server、gRPC server——都不是手写 new 出来的,是 Wire 在编译期织起来的。这一节逐行拆。</p><h3 id="_3-1-injector-桩" tabindex="-1"><a class="header-anchor" href="#_3-1-injector-桩"><span>3.1 injector 桩</span></a></h3><p>每个服务的 <code>cmd/server/wire.go</code>:</p><div class="language-go line-numbers-mode" data-highlighter="prismjs" data-ext="go"><pre><code><span class="line"><span class="token comment">//go:build wireinject</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">package</span> server</span>
<span class="line"></span>
<span class="line"><span class="token keyword">import</span> <span class="token punctuation">(</span></span>
<span class="line">    <span class="token string">&quot;github.com/google/wire&quot;</span></span>
<span class="line">    serverProviders <span class="token string">&quot;go-wind-shop/app/admin/service/internal/server/providers&quot;</span></span>
<span class="line">    serviceProviders <span class="token string">&quot;go-wind-shop/app/admin/service/internal/service/providers&quot;</span></span>
<span class="line">    dataProviders <span class="token string">&quot;go-wind-shop/app/admin/service/internal/data/providers&quot;</span></span>
<span class="line"><span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">func</span> <span class="token function">initApp</span><span class="token punctuation">(</span>ctx <span class="token operator">*</span>bootstrap<span class="token punctuation">.</span>Context<span class="token punctuation">)</span> <span class="token punctuation">(</span><span class="token operator">*</span>kratos<span class="token punctuation">.</span>App<span class="token punctuation">,</span> <span class="token keyword">func</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">,</span> <span class="token builtin">error</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token function">panic</span><span class="token punctuation">(</span>wire<span class="token punctuation">.</span><span class="token function">Build</span><span class="token punctuation">(</span></span>
<span class="line">        serverProviders<span class="token punctuation">.</span>ProviderSet<span class="token punctuation">,</span></span>
<span class="line">        serviceProviders<span class="token punctuation">.</span>ProviderSet<span class="token punctuation">,</span></span>
<span class="line">        dataProviders<span class="token punctuation">.</span>ProviderSet<span class="token punctuation">,</span></span>
<span class="line">        newApp<span class="token punctuation">,</span></span>
<span class="line">    <span class="token punctuation">)</span><span class="token punctuation">)</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><code>//go:build wireinject</code> 构建标签让这个文件只在 <code>wire</code> 工具运行时参与编译,正常构建忽略它。<code>wire.Build</code> 列出三个 ProviderSet 和 <code>newApp</code>(kratos.App 的组装函数)。</p><h3 id="_3-2-providerset-依赖图的节点" tabindex="-1"><a class="header-anchor" href="#_3-2-providerset-依赖图的节点"><span>3.2 ProviderSet:依赖图的节点</span></a></h3><p>三个 ProviderSet 分层定义依赖。admin BFF 的 <code>internal/data/providers/wire_set.go</code>:</p><div class="language-go line-numbers-mode" data-highlighter="prismjs" data-ext="go"><pre><code><span class="line"><span class="token keyword">var</span> ProviderSet <span class="token operator">=</span> wire<span class="token punctuation">.</span><span class="token function">NewSet</span><span class="token punctuation">(</span></span>
<span class="line">    data<span class="token punctuation">.</span>NewRedisClient<span class="token punctuation">,</span>           <span class="token comment">// Redis 工厂</span></span>
<span class="line">    data<span class="token punctuation">.</span>NewMinIoClient<span class="token punctuation">,</span>           <span class="token comment">// MinIO 工厂</span></span>
<span class="line">    data<span class="token punctuation">.</span>NewDiscovery<span class="token punctuation">,</span>             <span class="token comment">// etcd 服务发现工厂</span></span>
<span class="line">    data<span class="token punctuation">.</span>NewAuthorizer<span class="token punctuation">,</span>            <span class="token comment">// Casbin/OPA 授权引擎工厂</span></span>
<span class="line">    auth<span class="token punctuation">.</span>NewTokenChecker<span class="token punctuation">,</span>          <span class="token comment">// token 校验器(连 core authentication gRPC)</span></span>
<span class="line">    data<span class="token punctuation">.</span>NewBrandServiceClient<span class="token punctuation">,</span>    <span class="token comment">// ↓ 以下全是 core gRPC client 工厂</span></span>
<span class="line">    data<span class="token punctuation">.</span>NewProductServiceClient<span class="token punctuation">,</span></span>
<span class="line">    data<span class="token punctuation">.</span>NewOrderServiceClient<span class="token punctuation">,</span></span>
<span class="line">    data<span class="token punctuation">.</span>NewCartServiceClient<span class="token punctuation">,</span></span>
<span class="line">    <span class="token comment">// ... 约 40 个</span></span>
<span class="line"><span class="token punctuation">)</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>注意这个 ProviderSet 里<strong>没有任何 <code>NewXxxRepo</code></strong>——BFF 不碰 DB,所以没有 repo 工厂。这是上文&quot;不碰 DB&quot;约束的代码体现。</p><p>对比 core 服务的 <code>internal/data/providers/wire_set.go</code>:</p><div class="language-go line-numbers-mode" data-highlighter="prismjs" data-ext="go"><pre><code><span class="line"><span class="token keyword">var</span> ProviderSet <span class="token operator">=</span> wire<span class="token punctuation">.</span><span class="token function">NewSet</span><span class="token punctuation">(</span></span>
<span class="line">    data<span class="token punctuation">.</span>NewRedisClient<span class="token punctuation">,</span></span>
<span class="line">    data<span class="token punctuation">.</span>NewEntClient<span class="token punctuation">,</span>            <span class="token comment">// ← Ent client 工厂(只有 core 有)</span></span>
<span class="line">    data<span class="token punctuation">.</span>NewDiscovery<span class="token punctuation">,</span></span>
<span class="line">    data<span class="token punctuation">.</span>NewBrandRepo<span class="token punctuation">,</span>            <span class="token comment">// ↓ 所有 repo 工厂</span></span>
<span class="line">    data<span class="token punctuation">.</span>NewBrandTranslationRepo<span class="token punctuation">,</span></span>
<span class="line">    data<span class="token punctuation">.</span>NewProductRepo<span class="token punctuation">,</span></span>
<span class="line">    data<span class="token punctuation">.</span>NewProductTranslationRepo<span class="token punctuation">,</span></span>
<span class="line">    <span class="token comment">// ... 约 50 个 repo</span></span>
<span class="line"><span class="token punctuation">)</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>core 的 ProviderSet 有 <code>NewEntClient</code> 和全部 repo,没有 gRPC client(它不调别的服务)。两个 ProviderSet 的差异,就是 BFF/核心 职责分层的代码证据。</p><h3 id="_3-3-wire-gen-go-织好的依赖图" tabindex="-1"><a class="header-anchor" href="#_3-3-wire-gen-go-织好的依赖图"><span>3.3 wire_gen.go:织好的依赖图</span></a></h3><p><code>make wire</code> 跑完,生成 <code>wire_gen.go</code>(<code>//go:build !wireinject</code>)。admin BFF 的 <code>wire_gen.go</code> 里,每个领域的装配模式都一样:</p><div class="language-go line-numbers-mode" data-highlighter="prismjs" data-ext="go"><pre><code><span class="line"><span class="token keyword">func</span> <span class="token function">initApp</span><span class="token punctuation">(</span>context <span class="token operator">*</span>bootstrap<span class="token punctuation">.</span>Context<span class="token punctuation">)</span> <span class="token punctuation">(</span><span class="token operator">*</span>kratos<span class="token punctuation">.</span>App<span class="token punctuation">,</span> <span class="token keyword">func</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">,</span> <span class="token builtin">error</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token comment">// ... discovery 先建</span></span>
<span class="line">    discovery <span class="token operator">:=</span> data<span class="token punctuation">.</span><span class="token function">NewDiscovery</span><span class="token punctuation">(</span>context<span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line">    <span class="token comment">// 每个领域:client → service</span></span>
<span class="line">    brandServiceClient <span class="token operator">:=</span> data<span class="token punctuation">.</span><span class="token function">NewBrandServiceClient</span><span class="token punctuation">(</span>context<span class="token punctuation">,</span> discovery<span class="token punctuation">)</span></span>
<span class="line">    brandService <span class="token operator">:=</span> service<span class="token punctuation">.</span><span class="token function">NewBrandService</span><span class="token punctuation">(</span>context<span class="token punctuation">,</span> brandServiceClient<span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line">    productServiceClient <span class="token operator">:=</span> data<span class="token punctuation">.</span><span class="token function">NewProductServiceClient</span><span class="token punctuation">(</span>context<span class="token punctuation">,</span> discovery<span class="token punctuation">)</span></span>
<span class="line">    productService <span class="token operator">:=</span> service<span class="token punctuation">.</span><span class="token function">NewProductService</span><span class="token punctuation">(</span>context<span class="token punctuation">,</span> productServiceClient<span class="token punctuation">)</span></span>
<span class="line">    <span class="token comment">// ... 几十个领域重复</span></span>
<span class="line"></span>
<span class="line">    <span class="token comment">// server 聚合所有 service</span></span>
<span class="line">    httpServer<span class="token punctuation">,</span> err <span class="token operator">:=</span> server<span class="token punctuation">.</span><span class="token function">NewRestServer</span><span class="token punctuation">(</span>context<span class="token punctuation">,</span> v<span class="token punctuation">,</span> userService<span class="token punctuation">,</span> <span class="token operator">...</span><span class="token punctuation">,</span> brandService<span class="token punctuation">,</span> productService<span class="token punctuation">,</span> <span class="token operator">...</span><span class="token punctuation">)</span></span>
<span class="line">    grpcServer<span class="token punctuation">,</span> err <span class="token operator">:=</span> server<span class="token punctuation">.</span><span class="token function">NewGrpcServer</span><span class="token punctuation">(</span>context<span class="token punctuation">,</span> grpcMiddlewares<span class="token punctuation">)</span></span>
<span class="line">    sseServer <span class="token operator">:=</span> server<span class="token punctuation">.</span><span class="token function">NewSseServer</span><span class="token punctuation">(</span>context<span class="token punctuation">,</span> internalMessageService<span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line">    app <span class="token operator">:=</span> <span class="token function">newApp</span><span class="token punctuation">(</span>context<span class="token punctuation">,</span> httpServer<span class="token punctuation">,</span> grpcServer<span class="token punctuation">,</span> sseServer<span class="token punctuation">)</span></span>
<span class="line">    <span class="token keyword">return</span> app<span class="token punctuation">,</span> <span class="token keyword">func</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">{</span> <span class="token comment">/* cleanup */</span> <span class="token punctuation">}</span><span class="token punctuation">,</span> <span class="token boolean">nil</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>整张依赖图被织成线性的初始化序列。<code>wire_gen.go</code> 体积很大(几百行),但它是&quot;可 diff 的依赖快照&quot;——review 它能快速看出谁依赖谁,比如某个 service 依赖了哪个 client,某个 server 聚合了哪些 service。</p><p>core 的 <code>wire_gen.go</code> 模式对称:<code>NewEntClient</code> → 每个 <code>NewXxxRepo</code>(注入 entClient)→ 每个 <code>NewXxxService</code>(注入 repo)→ <code>NewGrpcServer</code>(聚合所有 service)。</p><h3 id="_3-4-副作用导入-etcd-discovery-和-tracer" tabindex="-1"><a class="header-anchor" href="#_3-4-副作用导入-etcd-discovery-和-tracer"><span>3.4 副作用导入:etcd discovery 和 tracer</span></a></h3><p><code>wire_gen.go</code> 末尾有两个副作用导入:</p><div class="language-go line-numbers-mode" data-highlighter="prismjs" data-ext="go"><pre><code><span class="line"><span class="token keyword">import</span> <span class="token punctuation">(</span></span>
<span class="line">    <span class="token boolean">_</span> <span class="token string">&quot;github.com/tx7do/kratos-bootstrap/registry/etcd&quot;</span>   <span class="token comment">// etcd discovery 注册</span></span>
<span class="line">    <span class="token boolean">_</span> <span class="token string">&quot;github.com/tx7do/kratos-bootstrap/tracer&quot;</span>           <span class="token comment">// OTel tracer 注册</span></span>
<span class="line"><span class="token punctuation">)</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>这两个包的 <code>init()</code> 把自己注册进 kratos 的 registry/tracer 接口实现表里。etcd discovery 注册后,<code>data.NewDiscovery</code> 才能找到 etcd 实例;tracer 注册后,<code>trace.yaml</code> 的 OTLP 配置才生效。这是 Go 的&quot;registry 模式&quot;——实现通过 init 自注册,调用方按 config 选型。</p><h3 id="_3-5-wire-vs-运行时-di-的取舍" tabindex="-1"><a class="header-anchor" href="#_3-5-wire-vs-运行时-di-的取舍"><span>3.5 Wire vs 运行时 DI 的取舍</span></a></h3><p>这个项目选 Wire(编译期代码生成)而不是 dig/fx(运行时反射),取舍点:</p><table><thead><tr><th>维度</th><th>Wire</th><th>dig/fx</th></tr></thead><tbody><tr><td>依赖错误暴露</td><td>编译期(<code>wire</code> 命令报错)</td><td>运行时(启动 panic)</td></tr><tr><td>启动开销</td><td>零(纯构造函数调用)</td><td>反射+图构建</td></tr><tr><td>可读性</td><td>wire_gen.go 显式可 diff</td><td>隐式图,难追踪</td></tr><tr><td>产物体积</td><td>大(wire_gen.go)</td><td>无额外产物</td></tr></tbody></table><p>对一个有上百个 provider 的微服务,编译期暴露依赖错误的价值很大——少一个依赖,二进制编不出来,而不是上线后启动失败。代价是 wire_gen.go 体积大,但它是机器生成的,review 时当作&quot;依赖关系快照&quot;看,反而比运行时 DI 的隐式图透明。</p><p>这个取舍和选 Ent 的逻辑一致:<strong>用编译期保证换运行时安全。</strong></p><hr><h2 id="四、运行时配置-server-client-trace-逐行" tabindex="-1"><a class="header-anchor" href="#四、运行时配置-server-client-trace-逐行"><span>四、运行时配置:server / client / trace 逐行</span></a></h2><p>链路行为由 <code>configs/*.yaml</code> 决定。这一节把三个关键配置逐行讲清楚。</p><h3 id="_4-1-server-yaml-bff-暴露什么" tabindex="-1"><a class="header-anchor" href="#_4-1-server-yaml-bff-暴露什么"><span>4.1 server.yaml:BFF 暴露什么</span></a></h3><p><code>app/admin/service/configs/server.yaml</code> 的 server 段(上文环节 1 贴过)决定 BFF 暴露哪些传输。三个传输:rest(6600)、sse(6601)、grpc(0=关闭)。</p><p><code>rest.middleware.auth</code> 段:</p><div class="language-yaml line-numbers-mode" data-highlighter="prismjs" data-ext="yml"><pre><code><span class="line"><span class="token key atrule">middleware</span><span class="token punctuation">:</span></span>
<span class="line">  <span class="token key atrule">auth</span><span class="token punctuation">:</span></span>
<span class="line">    <span class="token key atrule">method</span><span class="token punctuation">:</span> <span class="token string">&quot;HS256&quot;</span></span>
<span class="line">    <span class="token key atrule">key</span><span class="token punctuation">:</span> <span class="token string">&quot;some_api_key&quot;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>这是 JWT 的签名方法和密钥。注意 <code>key: &quot;some_api_key&quot;</code> 是开发占位符——<strong>生产必须从 env/Secret 注入真实密钥</strong>。这个密钥如果泄漏,任何人都能伪造 admin token,是整个鉴权链的根。</p><blockquote><p>⚠️ 仓库里 <code>configs/*.yaml</code> 的所有密钥(key、aes_key、redis password、asynq redis)都是开发占位符,生产前必须外部化。这是&quot;开发友好 ≠ 生产就绪&quot;的典型。</p></blockquote><h3 id="_4-2-grpc-段的中间件开关" tabindex="-1"><a class="header-anchor" href="#_4-2-grpc-段的中间件开关"><span>4.2 grpc 段的中间件开关</span></a></h3><p>core 的 <code>server.yaml</code> 的 grpc 段:</p><div class="language-yaml line-numbers-mode" data-highlighter="prismjs" data-ext="yml"><pre><code><span class="line"><span class="token key atrule">server</span><span class="token punctuation">:</span></span>
<span class="line">  <span class="token key atrule">grpc</span><span class="token punctuation">:</span></span>
<span class="line">    <span class="token key atrule">addr</span><span class="token punctuation">:</span> <span class="token string">&quot;0.0.0.0:9000&quot;</span></span>
<span class="line">    <span class="token key atrule">middleware</span><span class="token punctuation">:</span></span>
<span class="line">      <span class="token key atrule">enable_logging</span><span class="token punctuation">:</span> <span class="token boolean important">true</span></span>
<span class="line">      <span class="token key atrule">enable_recovery</span><span class="token punctuation">:</span> <span class="token boolean important">true</span>        <span class="token comment"># panic 恢复</span></span>
<span class="line">      <span class="token key atrule">enable_tracing</span><span class="token punctuation">:</span> <span class="token boolean important">true</span>         <span class="token comment"># OTel 链路追踪</span></span>
<span class="line">      <span class="token key atrule">enable_validate</span><span class="token punctuation">:</span> <span class="token boolean important">true</span>        <span class="token comment"># protoc-gen-validate 入站校验</span></span>
<span class="line">      <span class="token key atrule">enable_circuit_breaker</span><span class="token punctuation">:</span> <span class="token boolean important">true</span></span>
<span class="line">      <span class="token key atrule">enable_metadata</span><span class="token punctuation">:</span> <span class="token boolean important">true</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>五个开关,每个对应一个 kratos 中间件。注意 <code>enable_validate: true</code>——入站请求会被 protoc-gen-validate 生成的校验代码检查,不通过直接 400,handler 拿不到非法输入。这把&quot;参数校验&quot;从业务代码里抽走,变成框架强制。</p><h3 id="_4-3-trace-yaml-链路追踪" tabindex="-1"><a class="header-anchor" href="#_4-3-trace-yaml-链路追踪"><span>4.3 trace.yaml:链路追踪</span></a></h3><p>三个服务的 <code>configs/trace.yaml</code> 内容一致:</p><div class="language-yaml line-numbers-mode" data-highlighter="prismjs" data-ext="yml"><pre><code><span class="line"><span class="token key atrule">trace</span><span class="token punctuation">:</span></span>
<span class="line">  <span class="token key atrule">endpoint</span><span class="token punctuation">:</span> <span class="token string">&quot;jaeger:4317&quot;</span></span>
<span class="line">  <span class="token key atrule">exporter</span><span class="token punctuation">:</span> <span class="token string">&quot;otlp-grpc&quot;</span></span>
<span class="line">  <span class="token key atrule">sampler</span><span class="token punctuation">:</span> <span class="token number">1.0</span></span>
<span class="line">  <span class="token key atrule">env</span><span class="token punctuation">:</span> <span class="token string">&quot;dev&quot;</span></span>
<span class="line">  <span class="token key atrule">insecure</span><span class="token punctuation">:</span> <span class="token boolean important">true</span></span>
<span class="line">  <span class="token key atrule">enable_trace_context</span><span class="token punctuation">:</span> <span class="token boolean important">true</span></span>
<span class="line">  <span class="token key atrule">enable_baggage</span><span class="token punctuation">:</span> <span class="token boolean important">true</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><ul><li><code>endpoint: &quot;jaeger:4317&quot;</code>:OTLP gRPC 导出到 Jaeger collector。</li><li><code>sampler: 1.0</code>:100% 采样。开发调试需要全采样,生产建议降到 0.01–0.1,否则存储和性能开销大。</li><li><code>insecure: true</code>:明文 OTLP。生产应启用 mTLS,防止 trace 数据(含敏感的 span 属性)被窃听。</li><li><code>enable_trace_context: true</code>:跨服务调用延续 trace context——这是 BFF → core 的 gRPC 调用能在 Jaeger 里连成一条链的前提。</li></ul><p>链路追踪在这套架构里的价值不只是排障。鉴权中间件会把 OTel 的 traceID 挂到 <code>UserViewer</code> 上,审计日志因此能关联到调用链——出问题时能在 Jaeger 里把&quot;哪个用户哪次操作在哪跳服务出错&quot;串起来。这是可观测性和安全审计的交叉点。</p><hr><h2 id="五、横向对比-三种架构形态" tabindex="-1"><a class="header-anchor" href="#五、横向对比-三种架构形态"><span>五、横向对比:三种架构形态</span></a></h2><p>把这套三服务 BFF 和另外两种形态对比,讲清楚各自适合什么。</p><h3 id="形态-a-单体-无-bff-无微服务" tabindex="-1"><a class="header-anchor" href="#形态-a-单体-无-bff-无微服务"><span>形态 A:单体(无 BFF,无微服务)</span></a></h3><p>一个进程,一套 DB,所有业务逻辑在一起。</p><ul><li><strong>优点</strong>:无网络开销,无分布式复杂度,调试简单。</li><li><strong>缺点</strong>:业务耦合,某个模块的 bug 拖垮全局;无法按模块独立扩缩容;DB 成为单点;数据访问边界靠业务自觉,容易越权。</li><li><strong>适合</strong>:小团队、早期项目、业务边界模糊时。</li></ul><p>这个项目没选它,核心原因是<strong>数据访问边界</strong>。多租户、多用户的行级隔离,在单体里只能靠每个查询手写 <code>WHERE tenant_id = ? AND user_id = ?</code>——漏一处就是越权。三服务架构把数据访问收敛到 core,行级隔离只在 core 一处用 Ent privacy 框架强制。这个收益是结构性的。</p><h3 id="形态-b-纯微服务-无-bff-每个业务服务直接暴露-http" tabindex="-1"><a class="header-anchor" href="#形态-b-纯微服务-无-bff-每个业务服务直接暴露-http"><span>形态 B:纯微服务(无 BFF,每个业务服务直接暴露 HTTP)</span></a></h3><p>order-service、payment-service、product-service 各自直接暴露 REST,前端直连每个服务。</p><ul><li><strong>优点</strong>:服务自治,技术栈可异构。</li><li><strong>缺点</strong>:前端要面对 N 个服务的鉴权、聚合、错误处理,逻辑下沉到前端;每个服务各自实现鉴权,容易不一致;接口面分散,难做统一的审计和限流。</li><li><strong>适合</strong>:前端聚合能力强的团队,或服务间正交性强的场景。</li></ul><p>这个项目没选它,核心原因是<strong>鉴权和审计的一致性</strong>。BFF 把鉴权和审计收敛到一处中间件链(环节 2),所有入站请求统一过 fail-closed 的 auth+authz,统一写防篡改审计。如果每个业务服务各自暴露 HTTP,要么每个服务各自实现这套(重复且易不一致),要么前端做聚合(鉴权下沉到前端,更不可控)。</p><h3 id="形态-c-本方案-三服务-bff-core" tabindex="-1"><a class="header-anchor" href="#形态-c-本方案-三服务-bff-core"><span>形态 C(本方案):三服务 BFF + core</span></a></h3><p>BFF 收敛传输面和鉴权/审计,core 收敛数据和业务逻辑。</p><ul><li><strong>优点</strong>:数据落点单点(core),鉴权审计单点(BFF 中间件),职责边界清晰;行级隔离框架级强制;新传输协议只需加 BFF,不动 core。</li><li><strong>代价</strong>:网络跳数多(BFF→core 一跳),latency 增加;部署复杂度上升(三个服务+中间件);开发体验上要在三个服务间跳代码。</li><li><strong>适合</strong>:需要强隔离、统一鉴权审计、多传输协议的企业级场景;不适合追求最低 latency 或快速原型。</li></ul><p>这个取舍是显式的:用一跳网络 latency 和部署复杂度,换数据访问收敛和鉴权审计一致性。对这个项目的目标场景(企业级、多租户、审计合规),这个交换值得。</p><hr><h2 id="六、三个实战踩坑点" tabindex="-1"><a class="header-anchor" href="#六、三个实战踩坑点"><span>六、三个实战踩坑点</span></a></h2><h3 id="_6-1-bff-的-grpc-端口必须关-0-0-0-0-0-不是随便写的" tabindex="-1"><a class="header-anchor" href="#_6-1-bff-的-grpc-端口必须关-0-0-0-0-0-不是随便写的"><span>6.1 BFF 的 gRPC 端口必须关:<code>0.0.0.0:0</code> 不是随便写的</span></a></h3><p><code>server.yaml</code> 里 BFF 的 <code>grpc.addr: &quot;0.0.0.0:0&quot;</code>。这个 0 不是&quot;让系统随机分配端口&quot;,而是 kratos 的约定——设为 0 表示不启动 gRPC server。</p><p>为什么必须关?如果 BFF 启动了 gRPC server,等于在 HTTP(6600)之外又开了一条直通 BFF 的 gRPC 通道。这条通道如果没配鉴权(或鉴权配错),就变成&quot;绕过 HTTP 中间件链直达 BFF service&quot;的旁路。环境里任何能连到这个 gRPC 端口的客户端,都能跳过环节 2 的审计和(部分)鉴权逻辑。</p><p>把端口设 0 从编译期就消除这个旁路——BFF 二进制根本没 gRPC server,想绕也绕不了。这是&quot;默认关闭不必要的能力&quot;的一个实例。</p><h3 id="_6-2-auto-ddl-的开发爽生产坑" tabindex="-1"><a class="header-anchor" href="#_6-2-auto-ddl-的开发爽生产坑"><span>6.2 auto-DDL 的开发爽生产坑</span></a></h3><p><code>core/.../configs/data.yaml</code> 里 <code>migrate: true</code>:</p><div class="language-go line-numbers-mode" data-highlighter="prismjs" data-ext="go"><pre><code><span class="line"><span class="token comment">// core/.../data/ent_client.go</span></span>
<span class="line">cli<span class="token punctuation">,</span> err <span class="token operator">:=</span> entBootstrap<span class="token punctuation">.</span><span class="token function">NewClient</span><span class="token punctuation">(</span>cfg<span class="token punctuation">,</span> <span class="token keyword">func</span><span class="token punctuation">(</span>drv <span class="token operator">*</span>sql<span class="token punctuation">.</span>Driver<span class="token punctuation">)</span> <span class="token operator">*</span>ent<span class="token punctuation">.</span>Client <span class="token punctuation">{</span></span>
<span class="line">    client <span class="token operator">:=</span> ent<span class="token punctuation">.</span><span class="token function">NewClient</span><span class="token punctuation">(</span>ent<span class="token punctuation">.</span><span class="token function">Driver</span><span class="token punctuation">(</span>drv<span class="token punctuation">)</span><span class="token punctuation">,</span> <span class="token operator">...</span><span class="token punctuation">)</span></span>
<span class="line">    <span class="token keyword">if</span> cfg<span class="token punctuation">.</span>Data<span class="token punctuation">.</span>Database<span class="token punctuation">.</span><span class="token function">GetMigrate</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">        client<span class="token punctuation">.</span>Schema<span class="token punctuation">.</span><span class="token function">Create</span><span class="token punctuation">(</span>ctx<span class="token punctuation">.</span><span class="token function">Context</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">,</span> migrate<span class="token punctuation">.</span><span class="token function">WithForeignKeys</span><span class="token punctuation">(</span><span class="token boolean">true</span><span class="token punctuation">)</span><span class="token punctuation">)</span>  <span class="token comment">// 启动时自动建表</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line">    <span class="token keyword">return</span> client</span>
<span class="line"><span class="token punctuation">}</span><span class="token punctuation">)</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>开发时很爽——改 Schema 重启就生效。生产坑:</p><ul><li><strong>无版本化</strong>:自动 DDL 不产生迁移文件,无法回滚,无法审计&quot;什么时候改了什么表&quot;。</li><li><strong>多实例并发</strong>:core 多副本同时启动时,多个实例并发跑 <code>Schema.Create</code> 可能冲突(建索引互相阻塞)。</li><li><strong>破坏性变更</strong>:删列、改列类型、删表,自动 DDL 会直接执行,可能丢数据。Ent 的 <code>Schema.Create</code> 默认不会删列,但某些 schema 变更仍可能导致数据丢失。</li></ul><p><strong>生产必须关 <code>migrate</code>,改用版本化迁移工具</strong>(atlas、golang-migrate),迁移文件进 git,通过 CI 流水线 apply。这是&quot;开发默认 ≠ 生产就绪&quot;的典型,踩过的人都懂。</p><h3 id="_6-3-client-yaml-的-120s-超时太长" tabindex="-1"><a class="header-anchor" href="#_6-3-client-yaml-的-120s-超时太长"><span>6.3 client.yaml 的 120s 超时太长</span></a></h3><p><code>app/admin/service/configs/client.yaml</code> 的 <code>timeout: 120s</code>。这个值对大多数 RPC 来说太长——电商场景的列表、详情、创建,通常应该在秒级返回。120s 意味着 core 卡死时,BFF 会挂 2 分钟才超时,期间占用连接池和 goroutine,容易拖垮 BFF。</p><p>踩坑点的解法:<strong>按 RPC 分级设超时</strong>。kratos 支持在 client config 里按方法设超时。生产建议把列表/详情类 RPC 设 5–10s,导出/批量类设 30–60s,没有 120s 的默认。这个仓库当前用统一 120s 是开发默认,需要生产前细化。</p><hr><h2 id="结语" tabindex="-1"><a class="header-anchor" href="#结语"><span>结语</span></a></h2><p>一个 REST 请求在这套架构里走了七个环节:HTTP 入站 → BFF 中间件链(日志、审计、鉴权)→ BFF service 转发 gRPC → etcd 服务发现连 core → core gRPC 中间件(viewer 重建)→ core service → repo(Ent 事务落库)。这条链路由 Wire 在编译期织好的依赖图支撑,由 <code>configs/*.yaml</code> 决定运行时行为。</p><p>这套结构的价值不是&quot;用了 BFF&quot;,而是<strong>职责边界的代码级强制</strong>:BFF 编译期不含数据访问依赖,core 编译期不含传输层依赖,数据落点和鉴权审计各自单点收敛。代价是网络跳数和部署复杂度——这是显式的交换,不是免费午餐。</p><p>仓库地址: GitHub <a href="https://github.com/tx7do/go-wind-shop" target="_blank" rel="noopener noreferrer">https://github.com/tx7do/go-wind-shop</a>, Gitee <a href="https://gitee.com/tx7do/go-wind-shop" target="_blank" rel="noopener noreferrer">https://gitee.com/tx7do/go-wind-shop</a>。 所有文中配置和代码均可逐行核对。</p>`,153)])])}const i=s(p,[["render",c]]),r=JSON.parse('{"path":"/posts/go-wind-shop-architecture-deep-dive.html","title":"GoWind Shop 架构剖析:一个 REST 请求穿越三服务 BFF 的七环链路","lang":"zh-CN","frontmatter":{"date":"2026-08-11T00:00:00.000Z","category":["GoWind风行"],"tag":["Golang","GoWind","Vue","Shop"],"sticky":10},"headers":[{"level":2,"title":"这篇在讲什么","slug":"这篇在讲什么","link":"#这篇在讲什么","children":[]},{"level":2,"title":"一、三服务 BFF:职责分层的硬约束","slug":"一、三服务-bff-职责分层的硬约束","link":"#一、三服务-bff-职责分层的硬约束","children":[]},{"level":2,"title":"二、请求全链路:七环节逐行追踪","slug":"二、请求全链路-七环节逐行追踪","link":"#二、请求全链路-七环节逐行追踪","children":[{"level":3,"title":"环节 1:HTTP 入站与路由分派","slug":"环节-1-http-入站与路由分派","link":"#环节-1-http-入站与路由分派","children":[]},{"level":3,"title":"环节 2:BFF 中间件链装配","slug":"环节-2-bff-中间件链装配","link":"#环节-2-bff-中间件链装配","children":[]},{"level":3,"title":"环节 3:BFF service 转发 gRPC","slug":"环节-3-bff-service-转发-grpc","link":"#环节-3-bff-service-转发-grpc","children":[]},{"level":3,"title":"环节 4:经 etcd 服务发现连 core","slug":"环节-4-经-etcd-服务发现连-core","link":"#环节-4-经-etcd-服务发现连-core","children":[]},{"level":3,"title":"环节 5:core gRPC 中间件","slug":"环节-5-core-grpc-中间件","link":"#环节-5-core-grpc-中间件","children":[]},{"level":3,"title":"环节 6:core service → repo","slug":"环节-6-core-service-→-repo","link":"#环节-6-core-service-→-repo","children":[]},{"level":3,"title":"环节 7:repo 落库(Ent 事务 + 级联)","slug":"环节-7-repo-落库-ent-事务-级联","link":"#环节-7-repo-落库-ent-事务-级联","children":[]},{"level":3,"title":"响应回程","slug":"响应回程","link":"#响应回程","children":[]}]},{"level":2,"title":"三、Wire 依赖注入:从 ProviderSet 到 wire_gen.go","slug":"三、wire-依赖注入-从-providerset-到-wire-gen-go","link":"#三、wire-依赖注入-从-providerset-到-wire-gen-go","children":[{"level":3,"title":"3.1 injector 桩","slug":"_3-1-injector-桩","link":"#_3-1-injector-桩","children":[]},{"level":3,"title":"3.2 ProviderSet:依赖图的节点","slug":"_3-2-providerset-依赖图的节点","link":"#_3-2-providerset-依赖图的节点","children":[]},{"level":3,"title":"3.3 wire_gen.go:织好的依赖图","slug":"_3-3-wire-gen-go-织好的依赖图","link":"#_3-3-wire-gen-go-织好的依赖图","children":[]},{"level":3,"title":"3.4 副作用导入:etcd discovery 和 tracer","slug":"_3-4-副作用导入-etcd-discovery-和-tracer","link":"#_3-4-副作用导入-etcd-discovery-和-tracer","children":[]},{"level":3,"title":"3.5 Wire vs 运行时 DI 的取舍","slug":"_3-5-wire-vs-运行时-di-的取舍","link":"#_3-5-wire-vs-运行时-di-的取舍","children":[]}]},{"level":2,"title":"四、运行时配置:server / client / trace 逐行","slug":"四、运行时配置-server-client-trace-逐行","link":"#四、运行时配置-server-client-trace-逐行","children":[{"level":3,"title":"4.1 server.yaml:BFF 暴露什么","slug":"_4-1-server-yaml-bff-暴露什么","link":"#_4-1-server-yaml-bff-暴露什么","children":[]},{"level":3,"title":"4.2 grpc 段的中间件开关","slug":"_4-2-grpc-段的中间件开关","link":"#_4-2-grpc-段的中间件开关","children":[]},{"level":3,"title":"4.3 trace.yaml:链路追踪","slug":"_4-3-trace-yaml-链路追踪","link":"#_4-3-trace-yaml-链路追踪","children":[]}]},{"level":2,"title":"五、横向对比:三种架构形态","slug":"五、横向对比-三种架构形态","link":"#五、横向对比-三种架构形态","children":[{"level":3,"title":"形态 A:单体(无 BFF,无微服务)","slug":"形态-a-单体-无-bff-无微服务","link":"#形态-a-单体-无-bff-无微服务","children":[]},{"level":3,"title":"形态 B:纯微服务(无 BFF,每个业务服务直接暴露 HTTP)","slug":"形态-b-纯微服务-无-bff-每个业务服务直接暴露-http","link":"#形态-b-纯微服务-无-bff-每个业务服务直接暴露-http","children":[]},{"level":3,"title":"形态 C(本方案):三服务 BFF + core","slug":"形态-c-本方案-三服务-bff-core","link":"#形态-c-本方案-三服务-bff-core","children":[]}]},{"level":2,"title":"六、三个实战踩坑点","slug":"六、三个实战踩坑点","link":"#六、三个实战踩坑点","children":[{"level":3,"title":"6.1 BFF 的 gRPC 端口必须关:0.0.0.0:0 不是随便写的","slug":"_6-1-bff-的-grpc-端口必须关-0-0-0-0-0-不是随便写的","link":"#_6-1-bff-的-grpc-端口必须关-0-0-0-0-0-不是随便写的","children":[]},{"level":3,"title":"6.2 auto-DDL 的开发爽生产坑","slug":"_6-2-auto-ddl-的开发爽生产坑","link":"#_6-2-auto-ddl-的开发爽生产坑","children":[]},{"level":3,"title":"6.3 client.yaml 的 120s 超时太长","slug":"_6-3-client-yaml-的-120s-超时太长","link":"#_6-3-client-yaml-的-120s-超时太长","children":[]}]},{"level":2,"title":"结语","slug":"结语","link":"#结语","children":[]}],"git":{"updatedTime":1786420471000,"contributors":[{"name":"Bobo","username":"Bobo","email":"yanglinbo@gmail.com","commits":1,"url":"https://github.com/Bobo"}],"changelog":[{"hash":"e2ce92e3de85c275b0b5b0183aebe03348e2dd79","time":1786420471000,"email":"yanglinbo@gmail.com","author":"Bobo","message":"feat: add posts."}]},"filePathRelative":"posts/go-wind-shop-architecture-deep-dive.md","excerpt":"\\n<h2>这篇在讲什么</h2>\\n<p>大多数微服务架构的文章停在\\"我们用了 BFF 模式\\"这种结论性描述,不讲 BFF 具体怎么装配、一个请求实际穿过了哪些代码、依赖图是怎么织起来的。这篇文章反过来:用一条真实的 <code>POST /admin/v1/mall/brands</code> 请求,把它从 HTTP 入站到 Ent 落库的每一个环节用代码钉死,再把支撑这条链路的 Wire 依赖注入和运行时配置逐行拆解。</p>\\n<p>文中所有代码和配置都来自一个真实仓库 go-wind-shop(GitHub: <a href=\\"https://github.com/tx7do/go-wind-shop\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">https://github.com/tx7do/go-wind-shop</a>, Gitee: <a href=\\"https://gitee.com/tx7do/go-wind-shop\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">https://gitee.com/tx7do/go-wind-shop</a>),标注了文件路径可核对。读完你会清楚三件事:这条链路怎么走、它由哪些配置决定、依赖图怎么从代码生成。</p>"}');export{i as comp,r as data};
